class CorrectionSource {
public:
    virtual std::vector<uint8_t> fetchNextMessage() = 0;
    virtual bool isConnected() const = 0;
    virtual ~CorrectionSource() = default;
};
class NtripCorrectionSource : public CorrectionSource {
public:
    std::vector<uint8_t> fetchNextMessage() override {
        return readFromSocket();
    }
    bool isConnected() const override { return connected_; }

private:
    std::vector<uint8_t> readFromSocket() { return {}; }
    bool connected_ = false;
};
void releaseSource(CorrectionSource* source) {
    delete source;
}

class KalmanFilterState {
public:
    const Eigen::MatrixXd& getCovariance() const { return covariance_; }
    void setCovariance(const Eigen::MatrixXd& p) {
        // Numerical noise can break symmetry; enforce the invariant here.
        covariance_ = 0.5 * (p + p.transpose());
    }
private:
    Eigen::MatrixXd covariance_;
};

