struct RtcmMessage { int messageType; std::vector<uint8_t> payload; };
int connectToCaster(const std::string& host, int port);
class RtcmStreamReader {
public:
    std::optional<RtcmMessage> readNextMessage() {
        uint8_t header[3];
        if (recv(socketFd_, header, sizeof(header), MSG_WAITALL) <= 0) {
            close(socketFd_);
            socketFd_ = connectToCaster(host_, port_);
            reconnectAttempts_++;
            return std::nullopt;
        }
        if (header[0] != 0xD3) return std::nullopt;
        uint16_t length = ((header[1] & 0x03) << 8) | header[2];
        std::vector<uint8_t> payload(length);
        recv(socketFd_, payload.data(), length, MSG_WAITALL);
        return RtcmMessage{(payload[0] << 4) | (payload[1] >> 4), std::move(payload)};
    }

private:
    int socketFd_;
    std::string host_;
    int port_;
    int reconnectAttempts_ = 0;
};

class SatelliteMeasurement {
public:
    explicit SatelliteMeasurement(double pseudorange) : pseudorange_(pseudorange) {
        isPlausible_ = pseudorange_ > 1.0e7 && pseudorange_ < 1.0e8;
    }

    double pseudorange() const { return pseudorange_; }
    void setPseudorange(double value) {
        pseudorange_ = value;
        isPlausible_ = value > 1.0e7 && value < 1.0e8;
    }

    bool isPlausible() const { return isPlausible_; }

private:
    double pseudorange_;
    bool isPlausible_;
};
void applyClockCorrection(SatelliteMeasurement& measurement, double clockBiasMeters) {
    measurement.setPseudorange(measurement.pseudorange() - clockBiasMeters);
}
